fn find_max(a: &[i32]) -> usize {
    // Since the array is guaranteed to be non-empty, we can safely unwrap
    a.iter()
        .enumerate()
        .max_by_key(|&(_, &value)| value)
        .map(|(index, _)| index)
        .unwrap()
}

